"""Gera scripts/i18n/{en,es}/historical.json (bandeiras históricas) a partir das traduções abaixo.
Nomes conferidos com os títulos equivalentes das Wikipédias em inglês e espanhol (scripts/i18n/wikipedia-historical.json),
mas no formato curto do jogo (o mesmo do português, com o esclarecimento entre parênteses quando ele existe lá).
Uso: python scripts/i18n/_gen-historical.py && node scripts/i18n/build-i18n.mjs
"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
entities = json.loads((ROOT / "public/data/legacy/historical.json").read_text(encoding="utf8"))["entities"]

