# as históricas acrescentadas depois do clássico (scripts/data/historical-*.json, juntadas por scripts/merge-historical.mjs) trazem as traduções junto
for path in sorted((ROOT / "scripts/data").glob("historical-*.json")):
    for entry in json.loads(path.read_text(encoding="utf8")):
        T[entry["id"]] = {"en": entry["en"], "es": entry["es"]}

missing = [e["id"] for e in entities if e["id"] not in T]
if missing:
    raise SystemExit(f"sem tradução: {missing}")
for locale in ["en", "es"]:
    out = {}
    for entity in entities:
        values = T[entity["id"]][locale]
        item = {"name": values[0]}
        for index, key in enumerate(["cap", "sucessor", "fato"], start=1):
            if entity.get(key):
                if len(values) <= index or not values[index]:
                    raise SystemExit(f"{entity['id']}: falta {key} em {locale}")
                item[key] = values[index]
        out[entity["id"]] = item
    (ROOT / f"scripts/i18n/{locale}/historical.json").write_text(json.dumps(out, ensure_ascii=False, indent=1) + "\n", encoding="utf8")
    print(f"{locale}: {len(out)} históricas")
